package com.bank.poolbudget;

import java.util.logging.Logger;

// Computes a SAFE per-instance pool size from the database's capacity.
public class PoolBudgetCalculator {
    private static final Logger log = Logger.getLogger(PoolBudgetCalculator.class.getName());

    private final int maxConnections;   // DB hard limit, e.g. 200
    private final int adminReserve;     // keep some for DBA/maintenance, e.g. 20

    public PoolBudgetCalculator(int maxConnections, int adminReserve) {
        this.maxConnections = maxConnections;
        this.adminReserve = adminReserve;
    }

    // Total connections an application fleet may use.
    public int usableBudget() {
        return maxConnections - adminReserve;
    }

    // Largest safe per-instance pool size given the number of instances.
    public int safePoolSizePerInstance(int instanceCount) {
        if (instanceCount <= 0) throw new IllegalArgumentException("instanceCount must be > 0");
        return usableBudget() / instanceCount;
    }

    // Validate a PROPOSED configuration and warn if it will break.
    public boolean isSafe(int instanceCount, int proposedPoolSize) {
        int demanded = instanceCount * proposedPoolSize;
        boolean safe = demanded <= usableBudget();
        if (!safe) {
            log.severe(() -> "UNSAFE: " + instanceCount + " × " + proposedPoolSize
                + " = " + demanded + " connections demanded, budget is only " + usableBudget()
                + " (DB will reject " + (demanded - usableBudget()) + " connections)");
        } else {
            log.info(() -> "SAFE: " + demanded + " ≤ budget " + usableBudget());
        }
        return safe;
    }
}
