package com.bank.poolbudget;

import java.util.logging.Logger;

public class PoolBudgetDemo {
    private static final Logger log = Logger.getLogger(PoolBudgetDemo.class.getName());

    public static void main(String[] args) {
        // PostgreSQL max_connections=200, reserve 20 for admin/maintenance.
        PoolBudgetCalculator calc = new PoolBudgetCalculator(200, 20);

        // The festival mistake: 12 instances × pool of 50.
        calc.isSafe(12, 50);   // UNSAFE: 600 demanded vs 180 budget

        // The correct size derived from the DB downward.
        int safeSize = calc.safePoolSizePerInstance(12);
        log.info(() -> "Correct per-instance pool size for 12 instances: " + safeSize);

        calc.isSafe(12, safeSize);  // SAFE
    }
}
